                        _mm256_mullo_epi32(v010, one_minus_s1),
                        _mm256_mullo_epi32(v110, shift1D)
                    ), SHIFT_BITS);
                __m256i v_01 = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v001, one_minus_s1),
                        _mm256_mullo_epi32(v101, shift1D)
                    ), SHIFT_BITS);
                __m256i v_11 = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v011, one_minus_s1),
                        _mm256_mullo_epi32(v111, shift1D)
                    ), SHIFT_BITS);

                /* Interpolate along G (dim 2) */
                __m256i v__0 = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v_00, one_minus_s2),
                        _mm256_mullo_epi32(v_10, shift2D)
                    ), SHIFT_BITS);
                __m256i v__1 = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v_01, one_minus_s2),
                        _mm256_mullo_epi32(v_11, shift2D)
                    ), SHIFT_BITS);

                /* Interpolate along B (dim 3) */
                result_ch[ch] = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v__0, one_minus_s3),
                        _mm256_mullo_epi32(v__1, shift3D)
                    ), SHIFT_BITS);

                /* Advance offsets to next channel */
                off_c000 = _mm256_add_epi32(off_c000, _mm256_set1_epi32(2));
                off_c100 = _mm256_add_epi32(off_c100, _mm256_set1_epi32(2));
                off_c010 = _mm256_add_epi32(off_c010, _mm256_set1_epi32(2));
                off_c110 = _mm256_add_epi32(off_c110, _mm256_set1_epi32(2));
                off_c001 = _mm256_add_epi32(off_c001, _mm256_set1_epi32(2));
                off_c101 = _mm256_add_epi32(off_c101, _mm256_set1_epi32(2));
                off_c011 = _mm256_add_epi32(off_c011, _mm256_set1_epi32(2));
                off_c111 = _mm256_add_epi32(off_c111, _mm256_set1_epi32(2));
            }

            /* Clip and pack: result_ch[ch] contains 8 x INT32 values for channel ch */
            /* Add rounding and shift for clip8 lookup */
            __m256i r_val = _mm256_srai_epi32(_mm256_add_epi32(result_ch[0], v_round), clip_shift);
            __m256i g_val = _mm256_srai_epi32(_mm256_add_epi32(result_ch[1], v_round), clip_shift);
            __m256i b_val = _mm256_srai_epi32(_mm256_add_epi32(result_ch[2], v_round), clip_shift);

            /* Now use clip8_lookups table to clip each value to [0, 255] */
            /* clip8_lookups is indexed by value + 640, result is UINT8 */
            /* We need to do this per-element since it's a table lookup */
            UINT32 out_pixels[8];
            INT32 r_arr[8], g_arr[8], b_arr[8], a_arr[8];
            _mm256_storeu_si256((__m256i *)r_arr, r_val);
            _mm256_storeu_si256((__m256i *)g_arr, g_val);
            _mm256_storeu_si256((__m256i *)b_arr, b_val);
            _mm256_storeu_si256((__m256i *)a_arr, a_bytes);

            int i;
            for (i = 0; i < 8; i++) {
                UINT8 rc = clip8_lookups[r_arr[i]];
                UINT8 gc = clip8_lookups[g_arr[i]];
                UINT8 bc = clip8_lookups[b_arr[i]];
                UINT8 ac = (UINT8)a_arr[i];
                out_pixels[i] = (ac << 24) | (bc << 16) | (gc << 8) | rc;
            }
            _mm256_storeu_si256((__m256i *)(rowOut + x * 4), _mm256_loadu_si256((const __m256i *)out_pixels));
        }

        /* Handle remaining pixels with scalar code */
        for (; x < xsize; x++) {
            UINT32 index1D_s = rowIn[x * 4 + 0] * scale1D;
            UINT32 index2D_s = rowIn[x * 4 + 1] * scale2D;
            UINT32 index3D_s = rowIn[x * 4 + 2] * scale3D;
            INT16 shift1D_s = (SCALE_MASK & index1D_s) >> (SCALE_BITS - SHIFT_BITS);
            INT16 shift2D_s = (SCALE_MASK & index2D_s) >> (SCALE_BITS - SHIFT_BITS);
            INT16 shift3D_s = (SCALE_MASK & index3D_s) >> (SCALE_BITS - SHIFT_BITS);
            int idx_s = 3 * table_index3D(
                index1D_s >> SCALE_BITS,
                index2D_s >> SCALE_BITS,
                index3D_s >> SCALE_BITS,
                size1D, size1D_2D);
            INT16 result[4], left[4], right[4];
            INT16 leftleft[4], leftright[4], rightleft[4], rightright[4];

            interpolate3(leftleft, &table[idx_s + 0], &table[idx_s + 3], shift1D_s);
            interpolate3(leftright, &table[idx_s + size1D * 3], &table[idx_s + size1D * 3 + 3], shift1D_s);
            interpolate3(left, leftleft, leftright, shift2D_s);

            interpolate3(rightleft, &table[idx_s + size1D_2D * 3], &table[idx_s + size1D_2D * 3 + 3], shift1D_s);
            interpolate3(rightright, &table[idx_s + size1D_2D * 3 + size1D * 3], &table[idx_s + size1D_2D * 3 + size1D * 3 + 3], shift1D_s);
            interpolate3(right, rightleft, rightright, shift2D_s);

            interpolate3(result, left, right, shift3D_s);

            UINT32 v = (rowIn[x * 4 + 3] << 24) |
                       (clip8(result[2]) << 16) |
                       (clip8(result[1]) << 8) |
                       clip8(result[0]);
            memcpy(rowOut + x * 4, &v, 4);
        }

        imIn += ysize > 1 ? (xsize * 4) : 0;
        imOut += ysize > 1 ? (xsize * 4) : 0;
    }
}

#endif /* __AVX2__ */

/*
 Transforms colors of imIn using provided 3D lookup table
 and puts the result in imOut. Returns imOut on success or 0 on error.

 imOut, imIn - images, should be the same size and may be the same image.
    Should have 3 or 4 channels.
 table_channels - number of channels in the lookup table, 3 or 4.
    Should be less or equal than number of channels in imOut image;
 size1D, size_2D and size3D - dimensions of provided table;
 table - flat table,
    array with table_channels * size1D * size2D * size3D elements,
    where channels are changed first, then 1D, then 2D, then 3D.
    Each element is signed 16-bit int where 0 is lowest output value
    and 255 << PRECISION_BITS (16320) is highest value.
*/
Imaging
ImagingColorLUT3D_linear(
    Imaging imOut,
    Imaging imIn,
    int table_channels,
    int size1D,
    int size2D,
    int size3D,
    INT16 *table) {
    /* This float to int conversion doesn't have rounding
       error compensation (+0.5) for two reasons:
       1. As we don't hit the highest value,
          we can use one extra bit for precision.
       2. For every pixel, we interpolate 8 elements from the table:
          current and +1 for every dimension and their combinations.
          If we hit the upper cells from the table,
          +1 cells will be outside of the table.
          With this compensation we never hit the upper cells
          but this also doesn't introduce any noticeable difference. */
    UINT32 scale1D = (size1D - 1) / 255.0 * (1 << SCALE_BITS);
    UINT32 scale2D = (size2D - 1) / 255.0 * (1 << SCALE_BITS);
    UINT32 scale3D = (size3D - 1) / 255.0 * (1 << SCALE_BITS);
    int size1D_2D = size1D * size2D;
    int x, y;
    ImagingSectionCookie cookie;

    if (table_channels < 3 || table_channels > 4) {
        PyErr_SetString(PyExc_ValueError, "table_channels could be 3 or 4");
        return NULL;
    }

    if (imIn->type != IMAGING_TYPE_UINT8 || imOut->type != IMAGING_TYPE_UINT8 ||
        imIn->bands < 3 || imOut->bands < table_channels) {
        return (Imaging)ImagingError_ModeError();
    }

    /* In case we have one extra band in imOut and don't have in imIn.*/
    if (imOut->bands > table_channels && imOut->bands > imIn->bands) {
        return (Imaging)ImagingError_ModeError();
    }

#if defined(__AVX2__)
    /* Use AVX2-optimized version for 3-channel tables on RGB/RGBA images */
    if (table_channels == 3 && imIn->bands >= 3 && imOut->bands >= 3) {
        _color_lut_3d_avx2_3ch(
            (UINT8 *)imOut->image[0],
            (const UINT8 *)imIn->image[0],
            imOut->xsize, imOut->ysize,
            size1D, size2D, size3D, table);
        return imOut;
    }
#endif

    /* Scalar fallback */
    ImagingSectionEnter(&cookie);
    for (y = 0; y < imOut->ysize; y++) {
        UINT8 *rowIn = (UINT8 *)imIn->image[y];
        char *rowOut = (char *)imOut->image[y];
        for (x = 0; x < imOut->xsize; x++) {
            UINT32 index1D = rowIn[x * 4 + 0] * scale1D;
            UINT32 index2D = rowIn[x * 4 + 1] * scale2D;
            UINT32 index3D = rowIn[x * 4 + 2] * scale3D;
            INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
            INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
            INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);
            int idx = table_channels * table_index3D(
                                           index1D >> SCALE_BITS,
                                           index2D >> SCALE_BITS,
                                           index3D >> SCALE_BITS,
                                           size1D,
                                           size1D_2D);
            INT16 result[4], left[4], right[4];
            INT16 leftleft[4], leftright[4], rightleft[4], rightright[4];

            if (table_channels == 3) {
                UINT32 v;
                interpolate3(leftleft, &table[idx + 0], &table[idx + 3], shift1D);
                interpolate3(
                    leftright,
                    &table[idx + size1D * 3],
                    &table[idx + size1D * 3 + 3],
                    shift1D);
                interpolate3(left, leftleft, leftright, shift2D);

                interpolate3(
                    rightleft,
                    &table[idx + size1D_2D * 3],
                    &table[idx + size1D_2D * 3 + 3],
                    shift1D);
                interpolate3(
                    rightright,
                    &table[idx + size1D_2D * 3 + size1D * 3],
                    &table[idx + size1D_2D * 3 + size1D * 3 + 3],
                    shift1D);
                interpolate3(right, rightleft, rightright, shift2D);

                interpolate3(result, left, right, shift3D);

                v = MAKE_UINT32(
                    clip8(result[0]),
                    clip8(result[1]),
                    clip8(result[2]),
                    rowIn[x * 4 + 3]);
                memcpy(rowOut + x * sizeof(v), &v, sizeof(v));
            }

            if (table_channels == 4) {
                UINT32 v;
                interpolate4(leftleft, &table[idx + 0], &table[idx + 4], shift1D);
                interpolate4(
                    leftright,
                    &table[idx + size1D * 4],
                    &table[idx + size1D * 4 + 4],
                    shift1D);
                interpolate4(left, leftleft, leftright, shift2D);

                interpolate4(
                    rightleft,
                    &table[idx + size1D_2D * 4],
                    &table[idx + size1D_2D * 4 + 4],
                    shift1D);
                interpolate4(
                    rightright,
                    &table[idx + size1D_2D * 4 + size1D * 4],
                    &table[idx + size1D_2D * 4 + size1D * 4 + 4],
                    shift1D);
                interpolate4(right, rightleft, rightright, shift2D);

                interpolate4(result, left, right, shift3D);

                v = MAKE_UINT32(
                    clip8(result[0]),
                    clip8(result[1]),
                    clip8(result[2]),
                    clip8(result[3]));
                memcpy(rowOut + x * sizeof(v), &v, sizeof(v));
            }
        }
    }
    ImagingSectionLeave(&cookie);

    return imOut;
}
