#include "Imaging.h"
#include "ImagingSIMD.h"
#include <math.h>

/* 8 bits for result. Table can overflow [0, 1.0] range,
   so we need extra bits for overflow and negative values.
   NOTE: This value should be the same as in _imaging/_prepare_lut_table() */
#define PRECISION_BITS (16 - 8 - 2)
#define PRECISION_ROUNDING (1 << (PRECISION_BITS - 1))

/* 8 - scales are multiplied on byte.
   6 - max index in the table
       (max size is 65, but index 64 is not reachable) */
#define SCALE_BITS (32 - 8 - 6)
#define SCALE_MASK ((1 << SCALE_BITS) - 1)

#define SHIFT_BITS (16 - 1)

static inline UINT8
clip8_val(int in) {
    return clip8_lookups[(in + PRECISION_ROUNDING) >> PRECISION_BITS];
}

static inline void
interpolate3(INT16 out[3], const INT16 a[3], const INT16 b[3], INT16 shift) {
    out[0] = (a[0] * ((1 << SHIFT_BITS) - shift) + b[0] * shift) >> SHIFT_BITS;
    out[1] = (a[1] * ((1 << SHIFT_BITS) - shift) + b[1] * shift) >> SHIFT_BITS;
    out[2] = (a[2] * ((1 << SHIFT_BITS) - shift) + b[2] * shift) >> SHIFT_BITS;
}

static inline void
interpolate4(INT16 out[4], const INT16 a[4], const INT16 b[4], INT16 shift) {
    out[0] = (a[0] * ((1 << SHIFT_BITS) - shift) + b[0] * shift) >> SHIFT_BITS;
    out[1] = (a[1] * ((1 << SHIFT_BITS) - shift) + b[1] * shift) >> SHIFT_BITS;
    out[2] = (a[2] * ((1 << SHIFT_BITS) - shift) + b[2] * shift) >> SHIFT_BITS;
    out[3] = (a[3] * ((1 << SHIFT_BITS) - shift) + b[3] * shift) >> SHIFT_BITS;
}

static inline int
table_index3D(int index1D, int index2D, int index3D, int size1D, int size1D_2D) {
    return index1D + index2D * size1D + index3D * size1D_2D;
}

#if defined(__AVX2__)

#include <immintrin.h>

/* AVX2-optimized version processing 8 pixels at a time for 3-channel tables */
static void
_color_lut_3d_avx2_3ch(
    Imaging imOut,
    Imaging imIn,
    int size1D, int size2D, int size3D,
    const INT16 *table)
{
    UINT32 scale1D = (size1D - 1) / 255.0 * (1 << SCALE_BITS);
    UINT32 scale2D = (size2D - 1) / 255.0 * (1 << SCALE_BITS);
    UINT32 scale3D = (size3D - 1) / 255.0 * (1 << SCALE_BITS);
    int size1D_2D = size1D * size2D;
    int x, y;
    ImagingSectionCookie cookie;

    __m256i v_scale1D = _mm256_set1_epi32(scale1D);
    __m256i v_scale2D = _mm256_set1_epi32(scale2D);
    __m256i v_scale3D = _mm256_set1_epi32(scale3D);
    __m256i v_scale_mask = _mm256_set1_epi32(SCALE_MASK);
    int shift_amount = SCALE_BITS - SHIFT_BITS;
    __m256i v_shift15 = _mm256_set1_epi32(1 << SHIFT_BITS);
    __m256i v_size1D = _mm256_set1_epi32(size1D);
    __m256i v_size1D_2D = _mm256_set1_epi32(size1D_2D);
    __m256i v_round = _mm256_set1_epi32(PRECISION_ROUNDING);
    int clip_shift = PRECISION_BITS;

    int s1d3 = size1D * 3;
    int s1d2d3 = size1D_2D * 3;
    __m256i v_s1d3 = _mm256_set1_epi32(s1d3);
    __m256i v_s1d2d3 = _mm256_set1_epi32(s1d2d3);

    ImagingSectionEnter(&cookie);
    for (y = 0; y < imOut->ysize; y++) {
        const UINT8 *rowIn = (const UINT8 *)imIn->image[y];
        UINT8 *rowOut = (UINT8 *)imOut->image[y];
        x = 0;

        for (; x <= imOut->xsize - 8; x += 8) {
            /* Load 8 pixels (32 bytes) */
            __m256i pixels = _mm256_loadu_si256((const __m256i *)(rowIn + x * 4));

            /* Extract R, G, B, A channels */
            __m256i r_bytes = _mm256_and_si256(pixels, _mm256_set1_epi32(0xFF));
            __m256i g_bytes = _mm256_and_si256(_mm256_srli_epi32(pixels, 8), _mm256_set1_epi32(0xFF));
            __m256i b_bytes = _mm256_and_si256(_mm256_srli_epi32(pixels, 16), _mm256_set1_epi32(0xFF));
            __m256i a_bytes = _mm256_and_si256(_mm256_srli_epi32(pixels, 24), _mm256_set1_epi32(0xFF));

            /* Compute indices */
            __m256i index1D = _mm256_mullo_epi32(r_bytes, v_scale1D);
            __m256i index2D = _mm256_mullo_epi32(g_bytes, v_scale2D);
            __m256i index3D = _mm256_mullo_epi32(b_bytes, v_scale3D);

            /* Extract shifts */
            __m256i shift1D = _mm256_srli_epi32(_mm256_and_si256(index1D, v_scale_mask), shift_amount);
            __m256i shift2D = _mm256_srli_epi32(_mm256_and_si256(index2D, v_scale_mask), shift_amount);
            __m256i shift3D = _mm256_srli_epi32(_mm256_and_si256(index3D, v_scale_mask), shift_amount);

            /* Compute table base indices */
            __m256i idx1 = _mm256_srli_epi32(index1D, SCALE_BITS);
            __m256i idx2 = _mm256_srli_epi32(index2D, SCALE_BITS);
            __m256i idx3 = _mm256_srli_epi32(index3D, SCALE_BITS);

            __m256i table_base = _mm256_mullo_epi32(
                _mm256_add_epi32(
                    idx1,
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(idx2, v_size1D),
                        _mm256_mullo_epi32(idx3, v_size1D_2D)
                    )
                ),
                _mm256_set1_epi32(3)
            );

            /* 8 corner offsets */
            __m256i off_c000 = table_base;
            __m256i off_c100 = _mm256_add_epi32(table_base, _mm256_set1_epi32(3));
            __m256i off_c010 = _mm256_add_epi32(table_base, v_s1d3);
            __m256i off_c110 = _mm256_add_epi32(table_base, _mm256_add_epi32(v_s1d3, _mm256_set1_epi32(3)));
            __m256i off_c001 = _mm256_add_epi32(table_base, v_s1d2d3);
            __m256i off_c101 = _mm256_add_epi32(table_base, _mm256_add_epi32(v_s1d2d3, _mm256_set1_epi32(3)));
            __m256i off_c011 = _mm256_add_epi32(table_base, _mm256_add_epi32(v_s1d2d3, v_s1d3));
            __m256i off_c111 = _mm256_add_epi32(table_base, _mm256_add_epi32(v_s1d2d3, _mm256_add_epi32(v_s1d3, _mm256_set1_epi32(3))));

            /* Process each channel */
            __m256i result_ch[3];
            int ch;

            for (ch = 0; ch < 3; ch++) {
                /* Gather from 8 corners - gather reads 32 bits, we want low 16 bits */
                __m256i v000 = _mm256_i32gather_epi32((const int *)table, off_c000, 2);
                __m256i v100 = _mm256_i32gather_epi32((const int *)table, off_c100, 2);
                __m256i v010 = _mm256_i32gather_epi32((const int *)table, off_c010, 2);
                __m256i v110 = _mm256_i32gather_epi32((const int *)table, off_c110, 2);
                __m256i v001 = _mm256_i32gather_epi32((const int *)table, off_c001, 2);
                __m256i v101 = _mm256_i32gather_epi32((const int *)table, off_c101, 2);
                __m256i v011 = _mm256_i32gather_epi32((const int *)table, off_c011, 2);
                __m256i v111 = _mm256_i32gather_epi32((const int *)table, off_c111, 2);

                /* Sign-extend low 16 bits to 32 bits */
                v000 = _mm256_srai_epi32(_mm256_slli_epi32(v000, 16), 16);
                v100 = _mm256_srai_epi32(_mm256_slli_epi32(v100, 16), 16);
                v010 = _mm256_srai_epi32(_mm256_slli_epi32(v010, 16), 16);
                v110 = _mm256_srai_epi32(_mm256_slli_epi32(v110, 16), 16);
                v001 = _mm256_srai_epi32(_mm256_slli_epi32(v001, 16), 16);
                v101 = _mm256_srai_epi32(_mm256_slli_epi32(v101, 16), 16);
                v011 = _mm256_srai_epi32(_mm256_slli_epi32(v011, 16), 16);
                v111 = _mm256_srai_epi32(_mm256_slli_epi32(v111, 16), 16);

                /* Trilinear interpolation */
                __m256i one_minus_s1 = _mm256_sub_epi32(v_shift15, shift1D);
                __m256i one_minus_s2 = _mm256_sub_epi32(v_shift15, shift2D);
                __m256i one_minus_s3 = _mm256_sub_epi32(v_shift15, shift3D);

                /* Interpolate along R */
                __m256i v_00 = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v000, one_minus_s1),
                        _mm256_mullo_epi32(v100, shift1D)
                    ), SHIFT_BITS);
                __m256i v_10 = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v010, one_minus_s1),
                        _mm256_mullo_epi32(v110, shift1D)
                    ), SHIFT_BITS);
                __m256i v_01 = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v001, one_minus_s1),
                        _mm256_mullo_epi32(v101, shift1D)
                    ), SHIFT_BITS);
                __m256i v_11 = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v011, one_minus_s1),
                        _mm256_mullo_epi32(v111, shift1D)
                    ), SHIFT_BITS);

                /* Interpolate along G */
                __m256i v__0 = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v_00, one_minus_s2),
                        _mm256_mullo_epi32(v_10, shift2D)
                    ), SHIFT_BITS);
                __m256i v__1 = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v_01, one_minus_s2),
                        _mm256_mullo_epi32(v_11, shift2D)
                    ), SHIFT_BITS);

                /* Interpolate along B */
                result_ch[ch] = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v__0, one_minus_s3),
                        _mm256_mullo_epi32(v__1, shift3D)
                    ), SHIFT_BITS);

                /* Advance to next channel */
                off_c000 = _mm256_add_epi32(off_c000, _mm256_set1_epi32(1));
                off_c100 = _mm256_add_epi32(off_c100, _mm256_set1_epi32(1));
                off_c010 = _mm256_add_epi32(off_c010, _mm256_set1_epi32(1));
                off_c110 = _mm256_add_epi32(off_c110, _mm256_set1_epi32(1));
                off_c001 = _mm256_add_epi32(off_c001, _mm256_set1_epi32(1));
                off_c101 = _mm256_add_epi32(off_c101, _mm256_set1_epi32(1));
                off_c011 = _mm256_add_epi32(off_c011, _mm256_set1_epi32(1));
                off_c111 = _mm256_add_epi32(off_c111, _mm256_set1_epi32(1));
            }

            /* Clip and pack */
            __m256i r_val = _mm256_srai_epi32(_mm256_add_epi32(result_ch[0], v_round), clip_shift);
            __m256i g_val = _mm256_srai_epi32(_mm256_add_epi32(result_ch[1], v_round), clip_shift);
            __m256i b_val = _mm256_srai_epi32(_mm256_add_epi32(result_ch[2], v_round), clip_shift);

            /* Extract to arrays for clip lookup and packing */
            UINT32 out_pixels[8] __attribute__((aligned(32)));
            INT32 r_arr[8], g_arr[8], b_arr[8], a_arr[8];
            _mm256_storeu_si256((__m256i *)r_arr, r_val);
            _mm256_storeu_si256((__m256i *)g_arr, g_val);
            _mm256_storeu_si256((__m256i *)b_arr, b_val);
            _mm256_storeu_si256((__m256i *)a_arr, a_bytes);

            int i;
            for (i = 0; i < 8; i++) {
                UINT8 rc = clip8_lookups[r_arr[i]];
                UINT8 gc = clip8_lookups[g_arr[i]];
                UINT8 bc = clip8_lookups[b_arr[i]];
                UINT8 ac = (UINT8)a_arr[i];
                out_pixels[i] = (ac << 24) | (bc << 16) | (gc << 8) | rc;
            }
            _mm256_storeu_si256((__m256i *)(rowOut + x * 4), _mm256_loadu_si256((const __m256i *)out_pixels));
        }

