            __m256i idx1 = _mm256_srli_epi32(index1D, SCALE_BITS);
            __m256i idx2 = _mm256_srli_epi32(index2D, SCALE_BITS);
            __m256i idx3 = _mm256_srli_epi32(index3D, SCALE_BITS);

            __m256i table_base = _mm256_mullo_epi32(
                _mm256_add_epi32(
                    idx1,
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(idx2, v_size1D),
                        _mm256_mullo_epi32(idx3, v_size1D_2D)
