            b101 = _mm256_srai_epi32(_mm256_slli_epi32(b101, 16), 16);
            b011 = _mm256_srai_epi32(_mm256_slli_epi32(b011, 16), 16);
            b111 = _mm256_srai_epi32(_mm256_slli_epi32(b111, 16), 16);

            /* Trilinear interpolation for all 3 channels in parallel */
            __m256i one_minus_s1 = _mm256_sub_epi32(v_shift15, shift1D);
            __m256i one_minus_s2 = _mm256_sub_epi32(v_shift15, shift2D);
            __m256i one_minus_s3 = _mm256_sub_epi32(v_shift15, shift3D);

            /* Interpolate along R dimension */
#define LERP3(a0, a1, shift, inv_shift) \
    _mm256_srai_epi32(_mm256_add_epi32( \
        _mm256_mullo_epi32(a0, inv_shift), \
        _mm256_mullo_epi32(a1, shift) \
    ), SHIFT_BITS)

            __m256i r_00 = LERP3(r000, r100, shift1D, one_minus_s1);
            __m256i r_10 = LERP3(r010, r110, shift1D, one_minus_s1);
            __m256i r_01 = LERP3(r001, r101, shift1D, one_minus_s1);
            __m256i r_11 = LERP3(r011, r111, shift1D, one_minus_s1);

            __m256i g_00 = LERP3(g000, g100, shift1D, one_minus_s1);
            __m256i g_10 = LERP3(g010, g110, shift1D, one_minus_s1);
            __m256i g_01 = LERP3(g001, g101, shift1D, one_minus_s1);
            __m256i g_11 = LERP3(g011, g111, shift1D, one_minus_s1);

            __m256i b_00 = LERP3(b000, b100, shift1D, one_minus_s1);
            __m256i b_10 = LERP3(b010, b110, shift1D, one_minus_s1);
            __m256i b_01 = LERP3(b001, b101, shift1D, one_minus_s1);
            __m256i b_11 = LERP3(b011, b111, shift1D, one_minus_s1);

            /* Interpolate along G dimension */
            __m256i r__0 = LERP3(r_00, r_10, shift2D, one_minus_s2);
            __m256i r__1 = LERP3(r_01, r_11, shift2D, one_minus_s2);
            __m256i g__0 = LERP3(g_00, g_10, shift2D, one_minus_s2);
            __m256i g__1 = LERP3(g_01, g_11, shift2D, one_minus_s2);
            __m256i b__0 = LERP3(b_00, b_10, shift2D, one_minus_s2);
            __m256i b__1 = LERP3(b_01, b_11, shift2D, one_minus_s2);

            /* Interpolate along B dimension */
            __m256i r_result = LERP3(r__0, r__1, shift3D, one_minus_s3);
            __m256i g_result = LERP3(g__0, g__1, shift3D, one_minus_s3);
            __m256i b_result = LERP3(b__0, b__1, shift3D, one_minus_s3);

            /* Clip to [0, 255<<PRECISION_BITS] range */
            r_result = _mm256_min_epi32(_mm256_max_epi32(r_result, v_zero), v_max_clip);
            g_result = _mm256_min_epi32(_mm256_max_epi32(g_result, v_zero), v_max_clip);
            b_result = _mm256_min_epi32(_mm256_max_epi32(b_result, v_zero), v_max_clip);

            /* Add rounding and shift to get [0, 255] */
            r_result = _mm256_srli_epi32(_mm256_add_epi32(r_result, v_round), PRECISION_BITS);
            g_result = _mm256_srli_epi32(_mm256_add_epi32(g_result, v_round), PRECISION_BITS);
            b_result = _mm256_srli_epi32(_mm256_add_epi32(b_result, v_round), PRECISION_BITS);

            /* Pack into 16-bit, then 8-bit with saturation */
            /* First pack R and G into 16-bit */
            __m256i rg_lo = _mm256_packs_epi32(r_result, g_result);
            __m256i b_a = _mm256_packs_epi32(b_result, a_bytes);

            /* Pack to 8-bit with unsigned saturation */
            __m256i packed = _mm256_packus_epi16(rg_lo, b_a);

            /* Now we have: [R0-3, G0-3, B0-3, A0-3, R4-7, G4-7, B4-7, A4-7]
               Need to rearrange to [R0,G0,B0,A0, R1,G1,B1,A1, ...] */
            __m128i lo = _mm256_castsi256_si128(packed);
            __m128i hi = _mm256_extracti128_si256(packed, 1);

            /* lo = [R0,R1,R2,R3, G0,G1,G2,G3, B0,B1,B2,B3, A0,A1,A2,A3]
               hi = [R4,R5,R6,R7, G4,G5,G6,G7, B4,B5,B6,B7, A4,A5,A6,A7]
               Need to interleave to RGBA */

            /* Unpack lo: [R0,G0,R1,G1, R2,G2,R3,G3] and [B0,A0,B1,A1, B2,A2,B3,A3] */
            __m128i rg_lo128 = _mm_unpacklo_epi8(
                _mm_shuffle_epi32(lo, _MM_SHUFFLE(3,1,2,0)),
                _mm_shuffle_epi32(lo, _MM_SHUFFLE(1,3,0,2))
            );

            /* Actually, let me use a simpler approach - store and rearrange */
            UINT8 tmp[32] __attribute__((aligned(32)));
            _mm256_storeu_si256((__m256i *)tmp, packed);

            /* tmp layout: [R0,R1,R2,R3, R4,R5,R6,R7, G0,G1,G2,G3, G4,G5,G6,G7,
                           B0,B1,B2,B3, B4,B5,B6,B7, A0,A1,A2,A3, A4,A5,A6,A7]
               Need: [R0,G0,B0,A0, R1,G1,B1,A1, ...] */
            int i;
            for (i = 0; i < 8; i++) {
                rowOut[(x+i)*4+0] = tmp[i];      /* R */
                rowOut[(x+i)*4+1] = tmp[8+i];    /* G */
                rowOut[(x+i)*4+2] = tmp[16+i];   /* B */
                rowOut[(x+i)*4+3] = tmp[24+i];   /* A */
            }
        }

        /* Handle remaining pixels with scalar code */
        for (; x < imOut->xsize; x++) {
            UINT32 index1D_s = rowIn[x * 4 + 0] * scale1D;
            UINT32 index2D_s = rowIn[x * 4 + 1] * scale2D;
            UINT32 index3D_s = rowIn[x * 4 + 2] * scale3D;
            INT16 shift1D_s = (SCALE_MASK & index1D_s) >> (SCALE_BITS - SHIFT_BITS);
            INT16 shift2D_s = (SCALE_MASK & index2D_s) >> (SCALE_BITS - SHIFT_BITS);
            INT16 shift3D_s = (SCALE_MASK & index3D_s) >> (SCALE_BITS - SHIFT_BITS);
            int idx_s = 3 * table_index3D(
                index1D_s >> SCALE_BITS,
                index2D_s >> SCALE_BITS,
                index3D_s >> SCALE_BITS,
                size1D, size1D_2D);
            INT16 result[4], left[4], right[4];
            INT16 leftleft[4], leftright[4], rightleft[4], rightright[4];

            interpolate3(leftleft, &table[idx_s + 0], &table[idx_s + 3], shift1D_s);
            interpolate3(leftright, &table[idx_s + size1D * 3], &table[idx_s + size1D * 3 + 3], shift1D_s);
            interpolate3(left, leftleft, leftright, shift2D_s);

            interpolate3(rightleft, &table[idx_s + size1D_2D * 3], &table[idx_s + size1D_2D * 3 + 3], shift1D_s);
            interpolate3(rightright, &table[idx_s + size1D_2D * 3 + size1D * 3], &table[idx_s + size1D_2D * 3 + size1D * 3 + 3], shift1D_s);
            interpolate3(right, rightleft, rightright, shift2D_s);

            interpolate3(result, left, right, shift3D_s);

            UINT32 v = (rowIn[x * 4 + 3] << 24) |
                       (clip8_val(result[2]) << 16) |
                       (clip8_val(result[1]) << 8) |
                       clip8_val(result[0]);
            memcpy(rowOut + x * 4, &v, 4);
        }
    }
    ImagingSectionLeave(&cookie);
}

#endif /* __AVX2__ */

Imaging
ImagingColorLUT3D_linear(
    Imaging imOut,
    Imaging imIn,
    int table_channels,
    int size1D,
    int size2D,
    int size3D,
    INT16 *table) {
    UINT32 scale1D = (size1D - 1) / 255.0 * (1 << SCALE_BITS);
    UINT32 scale2D = (size2D - 1) / 255.0 * (1 << SCALE_BITS);
    UINT32 scale3D = (size3D - 1) / 255.0 * (1 << SCALE_BITS);
    int size1D_2D = size1D * size2D;
    int x, y;
    ImagingSectionCookie cookie;

    if (table_channels < 3 || table_channels > 4) {
        PyErr_SetString(PyExc_ValueError, "table_channels could be 3 or 4");
        return NULL;
    }

    if (imIn->type != IMAGING_TYPE_UINT8 || imOut->type != IMAGING_TYPE_UINT8 ||
        imIn->bands < 3 || imOut->bands < table_channels) {
        return (Imaging)ImagingError_ModeError();
    }

    if (imOut->bands > table_channels && imOut->bands > imIn->bands) {
        return (Imaging)ImagingError_ModeError();
    }

#if defined(__AVX2__)
    if (table_channels == 3 && imIn->bands >= 3 && imOut->bands >= 3) {
        _color_lut_3d_avx2_3ch(imOut, imIn, size1D, size2D, size3D, table);
        return imOut;
    }
#endif

    /* Scalar fallback */
    ImagingSectionEnter(&cookie);
    for (y = 0; y < imOut->ysize; y++) {
        UINT8 *rowIn = (UINT8 *)imIn->image[y];
        char *rowOut = (char *)imOut->image[y];
        for (x = 0; x < imOut->xsize; x++) {
            UINT32 index1D = rowIn[x * 4 + 0] * scale1D;
            UINT32 index2D = rowIn[x * 4 + 1] * scale2D;
            UINT32 index3D = rowIn[x * 4 + 2] * scale3D;
            INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
            INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
            INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);
            int idx = table_channels * table_index3D(
                                           index1D >> SCALE_BITS,
                                           index2D >> SCALE_BITS,
                                           index3D >> SCALE_BITS,
                                           size1D,
                                           size1D_2D);
            INT16 result[4], left[4], right[4];
            INT16 leftleft[4], leftright[4], rightleft[4], rightright[4];

            if (table_channels == 3) {
                UINT32 v;
                interpolate3(leftleft, &table[idx + 0], &table[idx + 3], shift1D);
                interpolate3(
                    leftright,
                    &table[idx + size1D * 3],
                    &table[idx + size1D * 3 + 3],
                    shift1D);
                interpolate3(left, leftleft, leftright, shift2D);

                interpolate3(
                    rightleft,
                    &table[idx + size1D_2D * 3],
                    &table[idx + size1D_2D * 3 + 3],
                    shift1D);
                interpolate3(
                    rightright,
                    &table[idx + size1D_2D * 3 + size1D * 3],
                    &table[idx + size1D_2D * 3 + size1D * 3 + 3],
                    shift1D);
                interpolate3(right, rightleft, rightright, shift2D);

                interpolate3(result, left, right, shift3D);

                v = MAKE_UINT32(
                    clip8_val(result[0]),
                    clip8_val(result[1]),
                    clip8_val(result[2]),
                    rowIn[x * 4 + 3]);
                memcpy(rowOut + x * sizeof(v), &v, sizeof(v));
            }

            if (table_channels == 4) {
                UINT32 v;
                interpolate4(leftleft, &table[idx + 0], &table[idx + 4], shift1D);
                interpolate4(
                    leftright,
                    &table[idx + size1D * 4],
                    &table[idx + size1D * 4 + 4],
                    shift1D);
                interpolate4(left, leftleft, leftright, shift2D);

                interpolate4(
                    rightleft,
                    &table[idx + size1D_2D * 4],
                    &table[idx + size1D_2D * 4 + 4],
                    shift1D);
                interpolate4(
                    rightright,
                    &table[idx + size1D_2D * 4 + size1D * 4],
                    &table[idx + size1D_2D * 4 + size1D * 4 + 4],
                    shift1D);
                interpolate4(right, rightleft, rightright, shift2D);

                interpolate4(result, left, right, shift3D);

                v = MAKE_UINT32(
                    clip8_val(result[0]),
                    clip8_val(result[1]),
                    clip8_val(result[2]),
                    clip8_val(result[3]));
                memcpy(rowOut + x * sizeof(v), &v, sizeof(v));
            }
        }
    }
    ImagingSectionLeave(&cookie);

    return imOut;
}
