                v011 = _mm256_srai_epi32(_mm256_slli_epi32(v011, 16), 16);
                v111 = _mm256_srai_epi32(_mm256_slli_epi32(v111, 16), 16);

                __m256i one_minus_s1 = _mm256_sub_epi32(v_shift15, shift1D);
                __m256i one_minus_s2 = _mm256_sub_epi32(v_shift15, shift2D);
                __m256i one_minus_s3 = _mm256_sub_epi32(v_shift15, shift3D);

                /* Interpolate along R */
                __m256i v_00 = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v000, one_minus_s1),
                        _mm256_mullo_epi32(v100, shift1D)
                    ), SHIFT_BITS);
                __m256i v_10 = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v010, one_minus_s1),
                        _mm256_mullo_epi32(v110, shift1D)
                    ), SHIFT_BITS);
                __m256i v_01 = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v001, one_minus_s1),
                        _mm256_mullo_epi32(v101, shift1D)
                    ), SHIFT_BITS);
                __m256i v_11 = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v011, one_minus_s1),
                        _mm256_mullo_epi32(v111, shift1D)
                    ), SHIFT_BITS);

                /* Interpolate along G */
                __m256i v__0 = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v_00, one_minus_s2),
                        _mm256_mullo_epi32(v_10, shift2D)
                    ), SHIFT_BITS);
                __m256i v__1 = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v_01, one_minus_s2),
                        _mm256_mullo_epi32(v_11, shift2D)
                    ), SHIFT_BITS);

                /* Interpolate along B */
                result_ch[ch] = _mm256_srai_epi32(
                    _mm256_add_epi32(
                        _mm256_mullo_epi32(v__0, one_minus_s3),
                        _mm256_mullo_epi32(v__1, shift3D)
                    ), SHIFT_BITS);

                /* Advance to next channel */
                off_c000 = _mm256_add_epi32(off_c000, _mm256_set1_epi32(1));
                off_c100 = _mm256_add_epi32(off_c100, _mm256_set1_epi32(1));
                off_c010 = _mm256_add_epi32(off_c010, _mm256_set1_epi32(1));
                off_c110 = _mm256_add_epi32(off_c110, _mm256_set1_epi32(1));
                off_c001 = _mm256_add_epi32(off_c001, _mm256_set1_epi32(1));
                off_c101 = _mm256_add_epi32(off_c101, _mm256_set1_epi32(1));
                off_c011 = _mm256_add_epi32(off_c011, _mm256_set1_epi32(1));
                off_c111 = _mm256_add_epi32(off_c111, _mm256_set1_epi32(1));
            }

            /* SIMD clip: clamp to [0, 255<<PRECISION_BITS] */
            __m256i r_clipped = _mm256_min_epi32(_mm256_max_epi32(result_ch[0], v_zero), v_max_clip);
            __m256i g_clipped = _mm256_min_epi32(_mm256_max_epi32(result_ch[1], v_zero), v_max_clip);
            __m256i b_clipped = _mm256_min_epi32(_mm256_max_epi32(result_ch[2], v_zero), v_max_clip);

            /* Add rounding and shift to get [0, 255] */
            __m256i r_val = _mm256_srli_epi32(_mm256_add_epi32(r_clipped, v_round), clip_shift);
            __m256i g_val = _mm256_srli_epi32(_mm256_add_epi32(g_clipped, v_round), clip_shift);
            __m256i b_val = _mm256_srli_epi32(_mm256_add_epi32(b_clipped, v_round), clip_shift);

            /* Pack to 8-bit using saturating operations */
            /* packs_epi32: 32-bit -> 16-bit signed sat */
            __m256i rg = _mm256_packs_epi32(r_val, g_val);
            /* rg: lower128 = [R0-7 as 16-bit], upper128 = [G0-7 as 16-bit] */
            __m256i ba = _mm256_packs_epi32(b_val, a_bytes);
            /* ba: lower128 = [B0-7 as 16-bit], upper128 = [A0-7 as 16-bit] */

            /* packus_epi16: 16-bit -> 8-bit unsigned sat */
            __m256i packed = _mm256_packus_epi16(rg, ba);
            /* packed lower128 = [R0-7(8bit), G0-7(8bit)] */
            /* packed upper128 = [B0-7(8bit), A0-7(8bit)] */

            /* Rearrange: need [R0,G0,B0,A0, R1,G1,B1,A1, ...]
               Current: [R0,R1,R2,R3,R4,R5,R6,R7, G0,G1,G2,G3,G4,G5,G6,G7,
                         B0,B1,B2,B3,B4,B5,B6,B7, A0,A1,A2,A3,A4,A5,A6,A7]
               Use vpermd on 32-bit lanes to rearrange, then byte shuffle */

            /* Alternative: store to temp and rearrange in scalar */
            UINT8 tmp[32] __attribute__((aligned(32)));
            _mm256_storeu_si256((__m256i *)tmp, packed);

            int i;
            for (i = 0; i < 8; i++) {
                rowOut[(x+i)*4+0] = tmp[i];      /* R */
                rowOut[(x+i)*4+1] = tmp[8+i];    /* G */
                rowOut[(x+i)*4+2] = tmp[16+i];   /* B */
                rowOut[(x+i)*4+3] = tmp[24+i];   /* A */
            }
        }

        /* Handle remaining pixels with scalar code */
        for (; x < imOut->xsize; x++) {
            UINT32 index1D_s = rowIn[x * 4 + 0] * scale1D;
            UINT32 index2D_s = rowIn[x * 4 + 1] * scale2D;
            UINT32 index3D_s = rowIn[x * 4 + 2] * scale3D;
            INT16 shift1D_s = (SCALE_MASK & index1D_s) >> (SCALE_BITS - SHIFT_BITS);
            INT16 shift2D_s = (SCALE_MASK & index2D_s) >> (SCALE_BITS - SHIFT_BITS);
            INT16 shift3D_s = (SCALE_MASK & index3D_s) >> (SCALE_BITS - SHIFT_BITS);
            int idx_s = 3 * table_index3D(
                index1D_s >> SCALE_BITS,
                index2D_s >> SCALE_BITS,
                index3D_s >> SCALE_BITS,
                size1D, size1D_2D);
            INT16 result[4], left[4], right[4];
            INT16 leftleft[4], leftright[4], rightleft[4], rightright[4];

            interpolate3(leftleft, &table[idx_s + 0], &table[idx_s + 3], shift1D_s);
            interpolate3(leftright, &table[idx_s + size1D * 3], &table[idx_s + size1D * 3 + 3], shift1D_s);
            interpolate3(left, leftleft, leftright, shift2D_s);

            interpolate3(rightleft, &table[idx_s + size1D_2D * 3], &table[idx_s + size1D_2D * 3 + 3], shift1D_s);
            interpolate3(rightright, &table[idx_s + size1D_2D * 3 + size1D * 3], &table[idx_s + size1D_2D * 3 + size1D * 3 + 3], shift1D_s);
            interpolate3(right, rightleft, rightright, shift2D_s);

            interpolate3(result, left, right, shift3D_s);

            UINT32 v = (rowIn[x * 4 + 3] << 24) |
                       (clip8_val(result[2]) << 16) |
                       (clip8_val(result[1]) << 8) |
                       clip8_val(result[0]);
            memcpy(rowOut + x * 4, &v, 4);
        }
    }
    ImagingSectionLeave(&cookie);
}

