                off_c100 = _mm256_add_epi32(off_c100, _mm256_set1_epi32(1));
                off_c010 = _mm256_add_epi32(off_c010, _mm256_set1_epi32(1));
                off_c110 = _mm256_add_epi32(off_c110, _mm256_set1_epi32(1));
                off_c001 = _mm256_add_epi32(off_c001, _mm256_set1_epi32(1));
                off_c101 = _mm256_add_epi32(off_c101, _mm256_set1_epi32(1));
                off_c011 = _mm256_add_epi32(off_c011, _mm256_set1_epi32(1));
                off_c111 = _mm256_add_epi32(off_c111, _mm256_set1_epi32(1));
