            __m256i r_val = _mm256_srai_epi32(_mm256_add_epi32(result_ch[0], v_round), clip_shift);
            __m256i g_val = _mm256_srai_epi32(_mm256_add_epi32(result_ch[1], v_round), clip_shift);
            __m256i b_val = _mm256_srai_epi32(_mm256_add_epi32(result_ch[2], v_round), clip_shift);

