            interpolate3(leftright, &table[idx_s + size1D * 3], &table[idx_s + size1D * 3 + 3], shift1D_s);
            interpolate3(left, leftleft, leftright, shift2D_s);

            interpolate3(rightleft, &table[idx_s + size1D_2D * 3], &table[idx_s + size1D_2D * 3 + 3], shift1D_s);
