            b011 = _mm256_srai_epi32(_mm256_slli_epi32(b011, 16), 16);
            b111 = _mm256_srai_epi32(_mm256_slli_epi32(b111, 16), 16);

            /* Trilinear interpolation for all 3 channels in parallel */
            __m256i one_minus_s1 = _mm256_sub_epi32(v_shift15, shift1D);
            __m256i one_minus_s2 = _mm256_sub_epi32(v_shift15, shift2D);
            __m256i one_minus_s3 = _mm256_sub_epi32(v_shift15, shift3D);

#define LERP3(a0, a1, shift, inv_shift) \
    _mm256_srai_epi32(_mm256_add_epi32( \
        _mm256_mullo_epi32(a0, inv_shift), \
        _mm256_mullo_epi32(a1, shift) \
    ), SHIFT_BITS)

            /* Interpolate along R dimension */
            __m256i r_00 = LERP3(r000, r100, shift1D, one_minus_s1);
            __m256i r_10 = LERP3(r010, r110, shift1D, one_minus_s1);
            __m256i r_01 = LERP3(r001, r101, shift1D, one_minus_s1);
            __m256i r_11 = LERP3(r011, r111, shift1D, one_minus_s1);

            __m256i g_00 = LERP3(g000, g100, shift1D, one_minus_s1);
            __m256i g_10 = LERP3(g010, g110, shift1D, one_minus_s1);
            __m256i g_01 = LERP3(g001, g101, shift1D, one_minus_s1);
            __m256i g_11 = LERP3(g011, g111, shift1D, one_minus_s1);

            __m256i b_00 = LERP3(b000, b100, shift1D, one_minus_s1);
            __m256i b_10 = LERP3(b010, b110, shift1D, one_minus_s1);
            __m256i b_01 = LERP3(b001, b101, shift1D, one_minus_s1);
            __m256i b_11 = LERP3(b011, b111, shift1D, one_minus_s1);

            /* Interpolate along G dimension */
            __m256i r__0 = LERP3(r_00, r_10, shift2D, one_minus_s2);
            __m256i r__1 = LERP3(r_01, r_11, shift2D, one_minus_s2);
            __m256i g__0 = LERP3(g_00, g_10, shift2D, one_minus_s2);
            __m256i g__1 = LERP3(g_01, g_11, shift2D, one_minus_s2);
            __m256i b__0 = LERP3(b_00, b_10, shift2D, one_minus_s2);
            __m256i b__1 = LERP3(b_01, b_11, shift2D, one_minus_s2);

            /* Interpolate along B dimension */
            __m256i r_result = LERP3(r__0, r__1, shift3D, one_minus_s3);
            __m256i g_result = LERP3(g__0, g__1, shift3D, one_minus_s3);
            __m256i b_result = LERP3(b__0, b__1, shift3D, one_minus_s3);

            /* Add rounding and shift for clip8 lookup */
            __m256i r_val = _mm256_srai_epi32(_mm256_add_epi32(r_result, v_round), clip_shift);
            __m256i g_val = _mm256_srai_epi32(_mm256_add_epi32(g_result, v_round), clip_shift);
            __m256i b_val = _mm256_srai_epi32(_mm256_add_epi32(b_result, v_round), clip_shift);

            /* Extract to arrays for clip lookup and packing */
            UINT32 out_pixels[8] __attribute__((aligned(32)));
            INT32 r_arr[8], g_arr[8], b_arr[8], a_arr[8];
            _mm256_storeu_si256((__m256i *)r_arr, r_val);
            _mm256_storeu_si256((__m256i *)g_arr, g_val);
            _mm256_storeu_si256((__m256i *)b_arr, b_val);
            _mm256_storeu_si256((__m256i *)a_arr, a_bytes);

