        for (; x < imOut->xsize; x++) {
            UINT32 index1D_s = rowIn[x * 4 + 0] * scale1D;
            UINT32 index2D_s = rowIn[x * 4 + 1] * scale2D;
            UINT32 index3D_s = rowIn[x * 4 + 2] * scale3D;
