    __m256i g_10 = LERP(g010, g110, shift1D, one_minus_s1);
    __m256i g_01 = LERP(g001, g101, shift1D, one_minus_s1);
    __m256i g_11 = LERP(g011, g111, shift1D, one_minus_s1);
    __m256i b_00 = LERP(b000, b100, shift1D, one_minus_s1);
    __m256i b_10 = LERP(b010, b110, shift1D, one_minus_s1);
    __m256i b_01 = LERP(b001, b101, shift1D, one_minus_s1);
    __m256i b_11 = LERP(b011, b111, shift1D, one_minus_s1);

    __m256i r__0 = LERP(r_00, r_10, shift2D, one_minus_s2);
    __m256i r__1 = LERP(r_01, r_11, shift2D, one_minus_s2);
    __m256i g__0 = LERP(g_00, g_10, shift2D, one_minus_s2);
    __m256i g__1 = LERP(g_01, g_11, shift2D, one_minus_s2);
    __m256i b__0 = LERP(b_00, b_10, shift2D, one_minus_s2);
    __m256i b__1 = LERP(b_01, b_11, shift2D, one_minus_s2);

    __m256i r_result = LERP(r__0, r__1, shift3D, one_minus_s3);
    __m256i g_result = LERP(g__0, g__1, shift3D, one_minus_s3);
    __m256i b_result = LERP(b__0, b__1, shift3D, one_minus_s3);

    /* Add rounding and shift for clip8 lookup */
    __m256i r_val = _mm256_srai_epi32(_mm256_add_epi32(r_result, v_round), clip_shift);
    __m256i g_val = _mm256_srai_epi32(_mm256_add_epi32(g_result, v_round), clip_shift);
    __m256i b_val = _mm256_srai_epi32(_mm256_add_epi32(b_result, v_round), clip_shift);

    /* Extract and pack */
    UINT32 out_pixels[8] __attribute__((aligned(32)));
    INT32 r_arr[8], g_arr[8], b_arr[8], a_arr[8];
    _mm256_storeu_si256((__m256i *)r_arr, r_val);
    _mm256_storeu_si256((__m256i *)g_arr, g_val);
    _mm256_storeu_si256((__m256i *)b_arr, b_val);
    _mm256_storeu_si256((__m256i *)a_arr, a_bytes);

    int i;
    for (i = 0; i < 8; i++) {
        out_pixels[i] = ((UINT8)a_arr[i] << 24) | (clip8_lookups[b_arr[i]] << 16) |
                        (clip8_lookups[g_arr[i]] << 8) | clip8_lookups[r_arr[i]];
    }
    _mm256_storeu_si256((__m256i *)(rowOut + x * 4), _mm256_loadu_si256((const __m256i *)out_pixels));
}

static void
_color_lut_3d_avx2_3ch(
    Imaging imOut,
    Imaging imIn,
    int size1D, int size2D, int size3D,
    const INT16 *table)
{
    UINT32 scale1D = (size1D - 1) / 255.0 * (1 << SCALE_BITS);
    UINT32 scale2D = (size2D - 1) / 255.0 * (1 << SCALE_BITS);
    UINT32 scale3D = (size3D - 1) / 255.0 * (1 << SCALE_BITS);
    int size1D_2D = size1D * size2D;
    int x, y;
    ImagingSectionCookie cookie;

    __m256i v_scale1D = _mm256_set1_epi32(scale1D);
    __m256i v_scale2D = _mm256_set1_epi32(scale2D);
    __m256i v_scale3D = _mm256_set1_epi32(scale3D);
    __m256i v_scale_mask = _mm256_set1_epi32(SCALE_MASK);
    int shift_amount = SCALE_BITS - SHIFT_BITS;
    __m256i v_shift15 = _mm256_set1_epi32(1 << SHIFT_BITS);
    __m256i v_size1D = _mm256_set1_epi32(size1D);
    __m256i v_size1D_2D = _mm256_set1_epi32(size1D_2D);
    __m256i v_round = _mm256_set1_epi32(PRECISION_ROUNDING);
    int clip_shift = PRECISION_BITS;
    __m256i v_s1d3 = _mm256_set1_epi32(size1D * 3);
    __m256i v_s1d2d3 = _mm256_set1_epi32(size1D_2D * 3);

    ImagingSectionEnter(&cookie);
    for (y = 0; y < imOut->ysize; y++) {
        const UINT8 *rowIn = (const UINT8 *)imIn->image[y];
        UINT8 *rowOut = (UINT8 *)imOut->image[y];
        x = 0;

        /* Process 16 pixels per iteration (two 8-pixel batches) */
        for (; x <= imOut->xsize - 16; x += 16) {
            process_8_pixels(rowIn, rowOut, x, table,
                v_scale1D, v_scale2D, v_scale3D,
                v_scale_mask, shift_amount, v_shift15,
                v_size1D, v_size1D_2D, v_round, clip_shift,
                v_s1d3, v_s1d2d3);
            process_8_pixels(rowIn, rowOut, x + 8, table,
                v_scale1D, v_scale2D, v_scale3D,
                v_scale_mask, shift_amount, v_shift15,
                v_size1D, v_size1D_2D, v_round, clip_shift,
                v_s1d3, v_s1d2d3);
        }

        /* Handle remaining 8-pixel batch */
        for (; x <= imOut->xsize - 8; x += 8) {
            process_8_pixels(rowIn, rowOut, x, table,
                v_scale1D, v_scale2D, v_scale3D,
                v_scale_mask, shift_amount, v_shift15,
                v_size1D, v_size1D_2D, v_round, clip_shift,
                v_s1d3, v_s1d2d3);
        }

        /* Handle remaining pixels with scalar code */
        for (; x < imOut->xsize; x++) {
            UINT32 index1D_s = rowIn[x * 4 + 0] * scale1D;
            UINT32 index2D_s = rowIn[x * 4 + 1] * scale2D;
            UINT32 index3D_s = rowIn[x * 4 + 2] * scale3D;
            INT16 shift1D_s = (SCALE_MASK & index1D_s) >> (SCALE_BITS - SHIFT_BITS);
            INT16 shift2D_s = (SCALE_MASK & index2D_s) >> (SCALE_BITS - SHIFT_BITS);
            INT16 shift3D_s = (SCALE_MASK & index3D_s) >> (SCALE_BITS - SHIFT_BITS);
            int idx_s = 3 * table_index3D(
                index1D_s >> SCALE_BITS, index2D_s >> SCALE_BITS,
                index3D_s >> SCALE_BITS, size1D, size1D_2D);
            INT16 result[4], left[4], right[4];
            INT16 leftleft[4], leftright[4], rightleft[4], rightright[4];

            interpolate3(leftleft, &table[idx_s + 0], &table[idx_s + 3], shift1D_s);
            interpolate3(leftright, &table[idx_s + size1D * 3], &table[idx_s + size1D * 3 + 3], shift1D_s);
            interpolate3(left, leftleft, leftright, shift2D_s);
            interpolate3(rightleft, &table[idx_s + size1D_2D * 3], &table[idx_s + size1D_2D * 3 + 3], shift1D_s);
            interpolate3(rightright, &table[idx_s + size1D_2D * 3 + size1D * 3], &table[idx_s + size1D_2D * 3 + size1D * 3 + 3], shift1D_s);
            interpolate3(right, rightleft, rightright, shift2D_s);
            interpolate3(result, left, right, shift3D_s);

            UINT32 v = (rowIn[x * 4 + 3] << 24) |
                       (clip8_val(result[2]) << 16) |
                       (clip8_val(result[1]) << 8) |
                       clip8_val(result[0]);
            memcpy(rowOut + x * 4, &v, 4);
        }
    }
    ImagingSectionLeave(&cookie);
}

#endif /* __AVX2__ */

Imaging
ImagingColorLUT3D_linear(
    Imaging imOut,
    Imaging imIn,
    int table_channels,
    int size1D,
    int size2D,
    int size3D,
    INT16 *table) {
    UINT32 scale1D = (size1D - 1) / 255.0 * (1 << SCALE_BITS);
    UINT32 scale2D = (size2D - 1) / 255.0 * (1 << SCALE_BITS);
    UINT32 scale3D = (size3D - 1) / 255.0 * (1 << SCALE_BITS);
    int size1D_2D = size1D * size2D;
    int x, y;
    ImagingSectionCookie cookie;

    if (table_channels < 3 || table_channels > 4) {
        PyErr_SetString(PyExc_ValueError, "table_channels could be 3 or 4");
        return NULL;
    }

    if (imIn->type != IMAGING_TYPE_UINT8 || imOut->type != IMAGING_TYPE_UINT8 ||
        imIn->bands < 3 || imOut->bands < table_channels) {
        return (Imaging)ImagingError_ModeError();
    }

    if (imOut->bands > table_channels && imOut->bands > imIn->bands) {
        return (Imaging)ImagingError_ModeError();
    }

#if defined(__AVX2__)
    if (table_channels == 3 && imIn->bands >= 3 && imOut->bands >= 3) {
        _color_lut_3d_avx2_3ch(imOut, imIn, size1D, size2D, size3D, table);
        return imOut;
    }
#endif

    /* Scalar fallback */
    ImagingSectionEnter(&cookie);
    for (y = 0; y < imOut->ysize; y++) {
        UINT8 *rowIn = (UINT8 *)imIn->image[y];
        char *rowOut = (char *)imOut->image[y];
        for (x = 0; x < imOut->xsize; x++) {
            UINT32 index1D = rowIn[x * 4 + 0] * scale1D;
            UINT32 index2D = rowIn[x * 4 + 1] * scale2D;
            UINT32 index3D = rowIn[x * 4 + 2] * scale3D;
            INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
            INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
            INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);
            int idx = table_channels * table_index3D(
                                           index1D >> SCALE_BITS,
                                           index2D >> SCALE_BITS,
                                           index3D >> SCALE_BITS,
                                           size1D,
                                           size1D_2D);
            INT16 result[4], left[4], right[4];
            INT16 leftleft[4], leftright[4], rightleft[4], rightright[4];

            if (table_channels == 3) {
                UINT32 v;
                interpolate3(leftleft, &table[idx + 0], &table[idx + 3], shift1D);
                interpolate3(leftright, &table[idx + size1D * 3], &table[idx + size1D * 3 + 3], shift1D);
                interpolate3(left, leftleft, leftright, shift2D);
                interpolate3(rightleft, &table[idx + size1D_2D * 3], &table[idx + size1D_2D * 3 + 3], shift1D);
                interpolate3(rightright, &table[idx + size1D_2D * 3 + size1D * 3], &table[idx + size1D_2D * 3 + size1D * 3 + 3], shift1D);
                interpolate3(right, rightleft, rightright, shift2D);
                interpolate3(result, left, right, shift3D);

                v = MAKE_UINT32(clip8_val(result[0]), clip8_val(result[1]),
                                clip8_val(result[2]), rowIn[x * 4 + 3]);
                memcpy(rowOut + x * sizeof(v), &v, sizeof(v));
            }

            if (table_channels == 4) {
                UINT32 v;
                interpolate4(leftleft, &table[idx + 0], &table[idx + 4], shift1D);
                interpolate4(leftright, &table[idx + size1D * 4], &table[idx + size1D * 4 + 4], shift1D);
                interpolate4(left, leftleft, leftright, shift2D);
                interpolate4(rightleft, &table[idx + size1D_2D * 4], &table[idx + size1D_2D * 4 + 4], shift1D);
                interpolate4(rightright, &table[idx + size1D_2D * 4 + size1D * 4], &table[idx + size1D_2D * 4 + size1D * 4 + 4], shift1D);
                interpolate4(right, rightleft, rightright, shift2D);
                interpolate4(result, left, right, shift3D);

                v = MAKE_UINT32(clip8_val(result[0]), clip8_val(result[1]),
                                clip8_val(result[2]), clip8_val(result[3]));
                memcpy(rowOut + x * sizeof(v), &v, sizeof(v));
            }
        }
    }
    ImagingSectionLeave(&cookie);

    return imOut;
}
